    topUpDesc: 'יש לנו מטבע אפליקציה משלנו, בדומה ל - Vbucks במטבעות Fortnite או TikTok, שלנו נקראים אסימוני DeHub. אלו יופיעו כמטבעות זהב ברחבי האפליקציה. הם משמשים לשירותי פרימיום כגון טיפים, מנויים ועוד. הגלישה היא בחינם, וכך גם פרסום בתוך הקצבה היומית שכל חשבון מקבל — אם אתם נרשמים באמצעות רשתות חברתיות, דוא"ל או SMS, אנחנו מממנים את כל עמלות הגז עבורכם. משתמשי ארנק משלמים בנזין ETH או BNB סטנדרטי. למעלה אסימונים ב -2 לחיצות למטה.',
