    feeTierDesc: 'מבנה העמלות המהפכני שלנו מתגמל את מחזיקי אסימוני DeHub עם עמלות פלטפורמה מופחתות באופן משמעותי. החל מעמלה סטנדרטית של 10%, כל דרגת תג שהורווחה באמצעות אחזקות אסימון מוגדלות מפחיתה את העמלות ב -0.69%, ובסופו של דבר מגיעה רק ל -1% עבור מחזיקי תג מגלודון - הפחתה של 99% עבור חברי הקהילה המסורים ביותר שלנו.',
