    step1Desc: 'פתח את dehub.io ולחץ על "Sign in" (כניסה). בחר בין גוגל, אפל, טלגרם, מייל, SMS, מפתח כניסה או תיקית מטבעות. תיקית לא-ממוסדת (non-custodial wallet) יוצרת עבורך מאחורי הקלעים – אתה מחזיק את המפתחות – וגז מומן, כך שאין צורך להזרים כסף לפני שתחל.',
    step2Title: 'התקנת פרופיל',
    step2Desc: 'בהגדרות → פרופיל, הוסף שם תצוגה, שם משתמש, איקון (avatar), תמונת כיסוי (cover image) וביו, ולחץ על החיבור לחשבונות חברתיים אחרים כדי שהפרופיל יראה את הנגישות הכוללת שלך. בחר נושא בהגדרות → מראה (Appearance) בזמן זה, ובצע את הסיור המודרך האופציונלי אם תרצו לראות סביב.',
    step3Title: 'יצירת הודעה ראשונה',
    step3Desc: 'לחץ על "Create" (יצירה). כתוב הודעה, הוסף תמונות, וידאו או קול, השתמש באופציה "Article" (מאמר) לכתיבה ארוכה, או חי. פרסום הוא חינם עד לקצב יומי – עשר הודעות טקסט וגיגהבייט של מדיה ביום ללא דגמה. עיצוב (מינט) של הודעה ברשת (on-chain) הוא אופציונלי וניתן לעשות מאוחר יותר.',
    step4Title: 'רווח מהקהל שלך',
    step4Desc: 'כל הודעה יכולה להיות מטופלת (טיפ) במטבעות דה-הוב. ממנה תוכל למכור מנויים, לפרסם הודעות בתשלום לראייה (pay-per-view), לקבוע סכום מינימלי לטיפים בהודעות ישירות, לפתוח חנות, לפרסם פרסים (bounties) ולשתף את הקישור לאפיליאט (affiliate link) כדי להרוויח מהאנשים שאתה מביא.',
    step5Title: 'החזק מטבעות כדי לקבל דגמה',
    step5Desc: 'החזקת או עריכת עמדה (staking) של מטבעות דה-הוב מקנה דגמה, מהצרעה (Crab) עד לגרזן (Megalodon). דגמה מפחיתה את העלויות, מגבירה את קצב ההודעות שלך, מפתחת כוחות על (SuperPowers) ומעניקה משקל לראיות, תגובות והצבעות שלך.',
    step6Title: 'שימוש בארנק',
    step6Desc: 'הארנק שלך מכיל אסימוני DeHub וקריפטו אחרים במספר רשתות. קנו אסימונים בכרטיס או עם הצפנה החל מ - $ 0.50, שלחו אותם לכל אחד בחינם, סחרו בבורסת DeHub והימרו כדי לטפס על סולם התג.',
    congratulations: '🎉 אתה מוכן',
