    pegDesc1: 'אסימון ה - DeHub הוא אסימון שירות. למטרות בתוך האפליקציה הוא מוצמד כרגע ל - $ 0.001 לאסימון, שהוא התעריף שמופיע בעת הקנייה דרך שער הפיאט והתעריף המשמש לתמחור בתוך האפליקציה. PEG זה קיים כדי לשמור על הכלכלה בתוך האפליקציה יציבה וצפויה בזמן שהרשת גדלה — זהו שיעור חשבונאות פנימי, לא רצפה, ערבות או הבטחה לערך עתידי.',
