    disclaimer: 'כתב ויתור',
    disclaimerNoApy: 'חשוב: בעוד שהחזקת אסימוני DeHub מעניקה בעלות ברשת DeHub ומקנה לסטייקרים נתח מרווחי הפרוטוקול, אין APY מוגדר, אין שיעור תשואה מובטח ואין ציפייה לרווח מכל סוג שהוא. כל ההפצות תלויות לחלוטין בביצועי הרשת ובהכנסות שהפרוטוקול מייצר בפועל בתקופה נתונה. הבונוסים עשויים להיות נמוכים יותר מכל תקופה קודמת, ועשויים להיות אפס. שום דבר בדף זה אינו הבטחה, השלכה או הצעה להחזרה, ושום דבר כאן אינו ייעוץ פיננסי.',
    disclaimerText: 'אסימונים של DeHub הם אך ורק למטרות שירות באותו אופן שבו כל אסימונים או מטבעות דיגיטליים בתוך המשחק או בתוך האפליקציה אינם השקעה. מכיוון שהאסימון שלנו חי בשרשרת, אנחנו יכולים להציע שירות נוסף כמו גם רמות חסרות תקדים של שקיפות ניתנת לאימות. הנתונים לעיל נאספים אך ורק למטרות שקיפות, חינוך ואינפורמציה בלבד. DeHub וכל החברות המסונפות אליה אינן נושאות באחריות להפסדים כספיים שנגרמו כתוצאה מרכישת כל אסימון או NFT שאנו משחררים. השווקים תנודתיים מאוד. אתם עלולים גם להפסיד את כל כספכם עקב שגיאות בלתי צפויות כגון כשלים בכשירות, שגיאות טכניות, פריצות וכן הלאה. לכן, אתה צריך להוציא רק את מה שאתה יכול להרשות לעצמך להפסיד.',
